function updateAppearance() {
  const act = activeLayerIndex();
  // planes
  for (let k = 0; k < NL; k++) {
    const on = act < 0 || k === act;
    outlineMats[k].color.setHex(act === k ? 0x000000 : (on ? 0x444444 : 0xcfcfcf));
    gridMats[k].opacity = on ? 1 : 0.25;
    for (let c = 0; c < 2; c++) {
      const base = new THREE.Color(c ? BLUE : RED);
      let f = 0;
      if (!on) f = 0.86;
      if (hoverIdx >= 0) f = Math.max(f, 0.82);
      dotMat[k][c].color.copy(base).lerp(WHITE, f);
      dotMat[k][c].opacity = on ? 1 : 0.55;
    }
  }
  hullObj.material.opacity = act < 0 ? 0.5 : 0.18;
  // trajectories
  for (let g = 0; g < NG; g++) {
    const gapOn = act < 0 || g === act - 1;
    const col = curveGeo[g].attributes.color;
    const arr = col.array;
    for (let i = 0; i < NP; i++) {
      const red = i < NPC;
      const r = red ? 0.91 : 0.10, gg = red ? 0.15 : 0.21, b = red ? 0.16 : 0.91;
      let mult = gapOn ? 1 : 0.07;
      if (hoverIdx >= 0) mult *= (i === hoverIdx ? 1.9 : 0.05);
      for (let v = 0; v < DV; v++) {
        const fade = 0.60 - 0.32 * (v / (DV - 1));
        const o = (i * DV + v) * 4;
        arr[o] = r; arr[o + 1] = gg; arr[o + 2] = b;
        arr[o + 3] = Math.max(0, Math.min(1, fade * mult));
      }
    }
    col.needsUpdate = true;
  }
  // legend highlight
  for (let n = 0; n < legendBoxes.length; n++) {
    const on = act === n + 1;
    legendBoxes[n].div.style.borderColor = on ? '#000' : '#111';
    legendBoxes[n].div.style.background = on ? '#c8e6ff' : '#fff';
    legendBoxes[n].div.style.fontWeight = on ? '700' : '400';
  }
}

/* ── legend column + training-iteration axis (HTML labels) ──────────────── */
const legendBoxes = [];
for (let n = 0; n < 6; n++) {
  const e = addLabel(OPS[n], new THREE.Vector3(-3.6, 1.1 + n * GAPY, 3.6), { fontSize: '12px' });
  Object.assign(e.div.style, {
    fontFamily: 'ui-monospace, Consolas, monospace',
    border: '1px solid #111', borderRadius: '9px',
    padding: '2px 8px', background: '#fff'
  });
  legendBoxes.push(e);
}
for (let k = 0; k < NL; k++) {
  const a = addLabel('&#8593;', new THREE.Vector3(-3.6, k * GAPY, 3.6), { fontSize: '19px' });
  a.div.style.lineHeight = '1';
}

const axis = addLabel(
  '<div style="display:flex;align-items:center;gap:8px;font-size:12px">' +
  '<span>Training iteration</span>' +
  '<div style="position:relative;width:230px;height:16px">' +
  '<div style="position:absolute;top:8px;left:0;width:100%;height:1.5px;background:#111"></div>' +
  '<div style="position:absolute;top:3px;right:-1px;width:0;height:0;border-left:9px solid #111;' +
  'border-top:5px solid transparent;border-bottom:5px solid transparent"></div>' +
  [2, 34, 66, 96].map(p => '<div style="position:absolute;top:4px;left:' + p +
    '%;width:1.5px;height:9px;background:#111"></div>').join('') +
  [18, 50, 81].map(p => '<div style="position:absolute;top:-1px;left:' + p +
    '%;transform:translateX(-50%);color:#111">&middot;&middot;&middot;</div>').join('') +
  '<div id="axMarker" style="position:absolute;top:0;left:2%;width:0;height:0;' +
  'border-bottom:8px solid #c00000;border-left:5px solid transparent;' +
  'border-right:5px solid transparent;transform:translateX(-50%)"></div>' +
  '</div></div>',
  new THREE.Vector3(0, -2.9, 0), { fontSize: '12px' });
const axMarker = axis.div.querySelector('#axMarker');

/* ── first build + camera ───────────────────────────────────────────────── */
writeCurves(); writeHull(); writeDots(); updateAppearance();
for (let g = 0; g < NG; g++) curveGeo[g].computeBoundingBox();

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});
controls.minPolarAngle = 0.18;
controls.maxPolarAngle = 1.46;
document.getElementById('btnReset').style.display = '';

/* ── slider / tween ─────────────────────────────────────────────────────── */
let iterTarget = 0, iterCur = 0;
const slider = document.getElementById('iterSlider');
const iterVal = document.getElementById('iterVal');

function setIter(v, immediate) {
  iterTarget = Math.max(0, Math.min(MAXIT, v));
  slider.value = String(iterTarget);
  iterVal.textContent = String(Math.round(iterTarget));
  axMarker.style.left = (2 + 94 * (iterTarget / MAXIT)) + '%';
  if (immediate) { iterCur = iterTarget; refreshGeometry(); }
}
function refreshGeometry() {
  computePositions(iterCur / MAXIT);
  writeCurves(); writeHull(); writeDots();
}
slider.addEventListener('input', () => setIter(parseFloat(slider.value)));

(function tween() {
  requestAnimationFrame(tween);
  if (Math.abs(iterCur - iterTarget) > 0.5) {
    iterCur += (iterTarget - iterCur) * 0.12;
    refreshGeometry();
  } else if (iterCur !== iterTarget) {
    iterCur = iterTarget; refreshGeometry();
  }
})();

/* ── layer-step buttons ─────────────────────────────────────────────────── */
const layerBtns = document.getElementById('layerBtns');
const btnMap = {};
['input', 'linear-1', 'relu-1', 'linear-2', 'relu-2', 'linear-3', 'softmax', 'all'].forEach(st => {
  const b = document.createElement('button');
  b.textContent = st;
  b.addEventListener('click', () => setLayerStep(st));
  layerBtns.appendChild(b);
  btnMap[st] = b;
});
function setLayerStep(st) {
  layerStep = st;
  for (const k in btnMap) btnMap[k].classList.toggle('active', k === st);
  updateAppearance();
}
setLayerStep('all');

/* ── hover trace ────────────────────────────────────────────────────────── */
const hoverRay = new THREE.Raycaster();
hoverRay.params.Points.threshold = 0.14;
const hoverInfo = document.getElementById('hoverInfo');
const ptr = new THREE.Vector2();

canvas.addEventListener('pointermove', (ev) => {
  const rect = canvas.getBoundingClientRect();
  ptr.x = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
  ptr.y = -((ev.clientY - rect.top) / rect.height) * 2 + 1;
  hoverRay.setFromCamera(ptr, camera);
  hoverRay.params.Points.threshold = 0.14;
  const hits = hoverRay.intersectObject(pickCloud, false);
  const idx = hits.length ? (hits[0].index % NP) : -1;
  if (idx !== hoverIdx) {
    hoverIdx = idx;
    updateAppearance(); writeDots();
    hoverInfo.innerHTML = idx < 0
      ? 'Hover a dot to trace its path. Drag to orbit the stack.'
      : 'Tracing datapoint #' + idx + ' &mdash; <b style="color:' +
        (idx < NPC ? '#E8262A' : '#1A35E8') + '">' + (idx < NPC ? 'red' : 'blue') +
        '</b> class, one continuous path through all 7 planes.';
  }
});
canvas.addEventListener('pointerleave', () => {
  if (hoverIdx !== -1) { hoverIdx = -1; updateAppearance(); writeDots(); }
});
canvas.addEventListener('click', () => {
  if (hoverIdx < 0) return;
  showPopup('Datapoint #' + hoverIdx + ' (' + (hoverIdx < NPC ? 'red' : 'blue') + ')',
    'This one input point is replotted on every plane: each dashed curve is the same ' +
    'point being moved by one layer (linear stretch, relu fold, or the final softmax ' +
    'squash onto the class simplex). Raise the training-iteration slider to watch its ' +
    'path migrate into the red bundle or the outward blue arc.');
});

/* ── guided demo ────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Untrained network', it: 0, ls: 'all',
    n: 'At iteration 0 the red and blue points stay mixed all the way up the stack — every plane looks like the tangled input cluster, so the network cannot separate the classes.' },
  { title: 'Step through one forward pass', it: 0, ls: 'relu-1',
    n: 'Walk upward one layer at a time. The linear layers stretch and rotate the cloud; the relu layers fold points against the axes; nothing yet pulls the colors apart.' },
  { title: 'Mid-training', it: 900, ls: 'all',
    n: 'Partway through training the upper planes begin to separate: red trajectories tighten toward a central bundle while blue ones start bowing out to one side.' },
  { title: 'The softmax plane', it: 1800, ls: 'softmax',
    n: 'Highlighting only the top plane shows where the decision actually lands — points are driven toward the corners of the probability simplex.' },
  { title: 'Late training', it: 3000, ls: 'all',
    n: 'By the final iteration the bottom plane is still fully intermingled, but the stack above it has cleanly split the classes: a tight vertical red bundle and blue trajectories swinging far out. Separation is learned, not present in the data layout.' }
];
let stepIdx = 0, playTimer = null;
const demoTitle = document.getElementById('demoTitle');
const demoNarr = document.getElementById('demoNarr');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  setIter(s.it, false);
  setLayerStep(s.ls);
  demoTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  demoNarr.textContent = s.n;
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
const playBtn = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  playBtn.textContent = '▶ Play'; playBtn.classList.remove('active');
}
playBtn.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  playBtn.textContent = '❚❚ Pause'; playBtn.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 4200);
});

setIter(0, true);
goToStep(0);
// @FIGURE_CODE_END
